class Solution {
  public int longestBalanced(String s) {
    int n = s.length(), ones = 0;
    for (int i = 0; i < n; i++) if (s.charAt(i) == '1') ones++;
    int zeros = n - ones, off = n + 2;
    int[] first = new int[2 * n + 5], second = new int[2 * n + 5];
    java.util.Arrays.fill(first, -1);
    java.util.Arrays.fill(second, -1);
    int best = 0, balance = 0;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + (s.charAt(i) == '1' ? 1 : -1);
    for (int e = 1; e <= n; e++) {
      int idx = prefix[e - 1] + off;
      if (first[idx] < 0) first[idx] = e - 1;
      else if (second[idx] < 0) second[idx] = e - 1;
      int b = prefix[e];
      int same = first[b + off];
      if (same >= 0) best = Math.max(best, e - same);
      for (int t = -2; t <= 2; t += 4) {
        int v = b - t + off;
        if (v < 0 || v >= first.length) continue;
        int[] cands = {first[v], second[v]};
        for (int l : cands) {
          if (l < 0) continue;
          int len = e - l, inside = (len - 2) / 2;
          boolean ok = t == 2 ? zeros - inside > 0 : ones - inside > 0;
          if (ok) best = Math.max(best, len);
        }
      }
    }
    return best;
  }
}
